import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type FeedSwipeAnimationProps = Record<string, any>;

// Sub-component for the Heart Icon
const HeartIcon: React.FC<{ color: string }> = ({ color }) => (
  <svg
    width="40"
    height="40"
    viewBox="0 0 24 24"
    fill={color}
    style={{ transition: "none" }}
  >
    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
  </svg>
);

const FeedSwipeAnimation: React.FC<FeedSwipeAnimationProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 12,
  images = [
    "https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?auto=format&fit=crop&w=1920&q=80",
    "https://images.unsplash.com/photo-1552519507-da3b142c6e3d?auto=format&fit=crop&w=1920&q=80",
    "https://images.unsplash.com/photo-1494976388531-d1058494cdd8?auto=format&fit=crop&w=1920&q=80",
  ],
  cardRadius = 40,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Constants for Layout and Animation
  const CARD_WIDTH = 1720;
  const CARD_HEIGHT = 967.5; // Exactly 16:9 ratio
  const SCROLL_DISTANCE = 3000; // Distance between centers of main cards
  
  // Calculate full screen scale to cover 1920x1080 perfectly
  const FULL_SCREEN_SCALE = Math.max(width / CARD_WIDTH, height / CARD_HEIGHT);

  // Timing variables
  const segmentFrames = Math.floor((durationInSeconds * fps) / Math.max(images.length, 1));
  const transitionDuration = Math.min(45, segmentFrames * 0.4); // Frames taken to swipe to next card

  // Global scroll position logic: accumulates scroll distance as we pass each transition window
  let currentScroll = 0;
  for (let i = 0; i < images.length - 1; i++) {
    const startScrollFrame = (i + 1) * segmentFrames - transitionDuration;
    const endScrollFrame = startScrollFrame + transitionDuration;
    
    const scrollAdded = interpolate(
      frame,
      [startScrollFrame, endScrollFrame],
      [0, SCROLL_DISTANCE],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
        easing: Easing.inOut(Easing.cubic),
      }
    );
    currentScroll += scrollAdded;
  }

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      
      {/* 
        Render Blurred Dummy Cards FIRST so they sit underneath the main cards if they ever overlap.
        We place two blurred cards in the vertical space between each main card.
      */}
      {images.map((_, i) => {
        if (i >= images.length - 1) return null; // No dummy cards after the last image

        const gapBaseY = i * SCROLL_DISTANCE;
        const dummy1Y = gapBaseY + 1000 - currentScroll;
        const dummy2Y = gapBaseY + 2000 - currentScroll;

        // Use the next image in the sequence as the dummy texture
        const dummyImgSrc = images[(i + 1) % images.length];

        return (
          <React.Fragment key={`dummy-group-${i}`}>
            {/* Dummy Card 1 */}
            <div
              style={{
                position: "absolute",
                left: width / 2 - CARD_WIDTH / 2,
                top: height / 2 - CARD_HEIGHT / 2,
                width: CARD_WIDTH,
                height: CARD_HEIGHT,
                borderRadius: cardRadius,
                overflow: "hidden",
                transform: `translateY(${dummy1Y}px)`,
                filter: "blur(20px)",
                opacity: 0.8,
                transition: "none",
              }}
            >
              <img src={dummyImgSrc} style={{ width: "100%", height: "100%", objectFit: "cover" }} alt="" />
            </div>
            
            {/* Dummy Card 2 */}
            <div
              style={{
                position: "absolute",
                left: width / 2 - CARD_WIDTH / 2,
                top: height / 2 - CARD_HEIGHT / 2,
                width: CARD_WIDTH,
                height: CARD_HEIGHT,
                borderRadius: cardRadius,
                overflow: "hidden",
                transform: `translateY(${dummy2Y}px)`,
                filter: "blur(35px)",
                opacity: 0.6,
                transition: "none",
              }}
            >
              <img src={dummyImgSrc} style={{ width: "100%", height: "100%", objectFit: "cover" }} alt="" />
            </div>
          </React.Fragment>
        );
      })}

      {/* Render Main Cards */}
      {images.map((imgSrc, i) => {
        const baseY = i * SCROLL_DISTANCE;
        const yOffset = baseY - currentScroll;

        // Intro animation only for the first card
        const introSpring = spring({
          frame,
          fps,
          config: { damping: 14, mass: 0.8 },
        });

        const scale = i === 0 
          ? interpolate(introSpring, [0, 1], [FULL_SCREEN_SCALE, 1]) 
          : 1;

        const currentBorderRadius = i === 0 
          ? interpolate(introSpring, [0, 1], [0, cardRadius]) 
          : cardRadius;

        // Heart Animation Logic
        // The heart triggers shortly after the card becomes centered
        const arrivalFrame = i * segmentFrames;
        const heartTriggerFrame = arrivalFrame + Math.floor(segmentFrames * 0.25);
        const isHeartActive = frame >= heartTriggerFrame;
        const heartColor = isHeartActive ? "#ff2b2b" : "#ffffff";

        // Heart "Pop" Scale
        let heartScale = 1;
        if (frame >= heartTriggerFrame && frame <= heartTriggerFrame + 15) {
          heartScale = interpolate(
            frame - heartTriggerFrame,
            [0, 5, 15],
            [1, 1.3, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
        }

        return (
          <div
            key={`main-card-${i}`}
            style={{
              position: "absolute",
              left: width / 2 - CARD_WIDTH / 2,
              top: height / 2 - CARD_HEIGHT / 2,
              width: CARD_WIDTH,
              height: CARD_HEIGHT,
              borderRadius: currentBorderRadius,
              overflow: "hidden",
              transform: `translateY(${yOffset}px) scale(${scale})`,
              transformOrigin: "center center",
              boxShadow: "0 25px 50px rgba(0,0,0,0.15)",
              transition: "none",
              backgroundColor: "#222", // Fallback color while loading
            }}
          >
            <img 
              src={imgSrc} 
              alt={`Feed image ${i}`} 
              style={{ width: "100%", height: "100%", objectFit: "cover", transition: "none" }} 
            />

            {/* Heart Button Overlay */}
            <div
              style={{
                position: "absolute",
                top: 40,
                right: 40,
                width: 90,
                height: 90,
                backgroundColor: "rgba(10, 10, 10, 0.85)",
                borderRadius: 24,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                transform: `scale(${heartScale})`,
                transition: "none",
                boxShadow: "0 10px 30px rgba(0,0,0,0.2)",
              }}
            >
              <HeartIcon color={heartColor} />
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default FeedSwipeAnimation;